    "mainEntity": [
        {
            "@type": "Question",
            "name": "Can I put personal items in the car?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "You can put personal items up to 100 lbs. in a box or single piece of luggage that will be in the trunk of the car during transport."
            }
        },
        {
            "@type": "Question",
            "name": "Is my vehicle insured during transport?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes, your vehicle will be covered by the carrier’s cargo insurance. Additionally, we have our own contingent cargo insurance, which\nprotects you for up to $250,000 should the trucker’s policy fail to fully cover a valid claim."
            }
        },
        {
            "@type": "Question",
            "name": "When is the vehicle going to be picked-up?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "After an order is placed, we search our car carrier network to find a trucker to transport your vehicle. We will assign the best one\navailable and give you an estimated pickup time. The trucker will call you to confirm the details ahead of schedule."
            }
        },
        {
            "@type": "Question",
            "name": "When will my vehicle be delivered?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "When you place an order, you will receive an estimated transit time for your shipment. This will give you a window for when your\ncar will be delivered. Transit times depend on moving distance. With each delivery being unique, it is possible that your car would\nbe delivered faster than the estimated transit time provided."
            }
        },
        {
            "@type": "Question",
            "name": "Can I track my vehicle online?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Online customer tracking is not available. For the most accurate, real-time location information on your shipment, directly contact your trucker for updates or email info@montway.com."
            }
        },
        {
            "@type": "Question",
            "name": "What is TruePrice Guarantee?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "TruePrice Guarantee is a customer-first pricing model, designed to make the auto transport process more transparent and protect customers against deceptive pricing practices. Simply book your order with Montway. Our TruePrice Guarantee ensures that your booked price is the price you’ll pay. If shipping rates increase during your 30-day protection period, we’ll cover the charge."
            }
        }
    ]
}

